    out = [row[:] for row in grid]
    marker_cols = {c for r in range(h) for c in range(w) if grid[r][c] == 5}

    for c in marker_cols:
        # Extend each nonzero color vertically from its position, preserving
        # the first color encountered when scanning upward from the markers.
        anchors = [(r, grid[r][c]) for r in range(h) if grid[r][c] not in (0, 5)]
        for r in range(h):
            if grid[r][c] != 0 or not anchors:
                continue
            below = [p for p in anchors if p[0] >= r]
            above = [p for p in anchors if p[0] < r]
            candidates = below or above
            _, color = min(candidates, key=lambda p: abs(p[0] - r))
            out[r][c] = color
    return out
